{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Row","children":["meter_column","content_column"],"itemMargin":8,"styles":{"width":300,"height":140,"padding":12,"borderRadius":22,"clip":true,"backgroundColor":"#fff1f3f5","alignItems":"center"}},{"id":"meter_column","component":"Column","children":["meter_ring","meter_value","remaining_text"],"itemMargin":4,"styles":{"width":88,"height":116,"alignItems":"center","justifyContent":"center"}},{"id":"meter_ring","component":"Progress","value":"{{ ${/data/screenTime/usedMinutes} }}","total":"{{ ${/data/screenTime/limitMinutes} }}","styles":{"type":"ring","color":"{{ ${/data/screenTime/meterColor} }}","width":70,"height":70}},{"id":"meter_value","component":"Text","content":"{{ ${/data/screenTime/usedText} }}","styles":{"width":88,"height":20,"fontSize":14,"fontWeight":700,"fontColor":"#e5000000","maxLines":1,"textAlign":"center"}},{"id":"remaining_text","component":"Text","content":"{{ ${/data/screenTime/remainingText} }}","styles":{"width":72,"height":16,"fontSize":12,"fontWeight":500,"fontColor":"#99000000","maxLines":1,"textAlign":"center"}},{"id":"content_column","component":"Column","children":["header_row","task_panel"],"itemMargin":8,"styles":{"width":180,"height":116,"justifyContent":"start"}},{"id":"header_row","component":"Row","children":["weather_group","settings_button"],"itemMargin":8,"styles":{"width":180,"height":32,"alignItems":"center","justifyContent":"spaceBetween"}},{"id":"weather_group","component":"Row","children":["weather_icon","weather_text"],"itemMargin":4,"styles":{"width":110,"height":32,"alignItems":"center"}},{"id":"weather_icon","component":"Image","src":"{{ ${/assets/weatherIcon} }}","styles":{"width":28,"height":28,"objectFit":"contain"}},{"id":"weather_text","component":"Text","content":"{{ ${/data/weather/current/condition} }}","styles":{"width":68,"height":18,"fontSize":14,"fontWeight":600,"fontColor":"#e5000000","maxLines":1}},{"id":"settings_button","component":"Button","label":"设置","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"parent_control"}}],"styles":{"width":62,"height":32,"fontSize":14,"fontWeight":"medium","fontColor":"#e5000000","backgroundColor":"#19000000","borderRadius":16}},{"id":"task_panel","component":"Column","children":["task_title","task_row_0","task_row_1"],"itemMargin":4,"styles":{"width":180,"height":76,"padding":{"top":8,"right":10,"bottom":8,"left":10},"borderRadius":16,"backgroundColor":"#ffffffff","justifyContent":"start"}},{"id":"task_title","component":"Text","content":"任务完成后再玩","styles":{"width":160,"height":16,"fontSize":12,"fontWeight":600,"fontColor":"#99000000","maxLines":1}},{"id":"task_row_0","component":"Checkbox","label":"{{ ${/data/tasks/0/title} }}","select":"{{ ${/data/tasks/0/checked} }}","value":"task_0","group":"anti_addiction_tasks","styles":{"width":160,"height":18,"selectedColor":"#ff64bb5c","unSelectedColor":"#33000000","shape":"rounded_square","mark":{"strokeColor":"#ffffffff","size":10,"strokeWidth":2}}},{"id":"task_row_1","component":"Checkbox","label":"{{ ${/data/tasks/1/title} }}","select":"{{ ${/data/tasks/1/checked} }}","value":"task_1","group":"anti_addiction_tasks","styles":{"width":160,"height":18,"selectedColor":"#ff64bb5c","unSelectedColor":"#33000000","shape":"rounded_square","mark":{"strokeColor":"#ffffffff","size":10,"strokeWidth":2}}}]}}
